-- Pack wars: a user starts a mini challenge, invites individual people by code or link,
-- and everyone is ranked by steps from the moment they joined. Counts as one of the 3 challenges.
create table if not exists public.packs (id uuid primary key default gen_random_uuid(), name text not null check (char_length(name) between 2 and 40), created_by uuid not null references auth.users(id), days int not null check (days between 1 and 30), starts_on date not null, ends_on date not null, join_code text not null unique, created_at timestamptz not null default now());
create table if not exists public.pack_members (pack_id uuid not null references public.packs(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, joined_on date not null, base int not null default 0, joined_at timestamptz not null default now(), primary key (pack_id, user_id));
alter table public.packs enable row level security; alter table public.pack_members enable row level security;

create or replace function public.pack_score(p_pack uuid, p_user uuid) returns bigint language sql stable security definer set search_path = public as $fn$ select coalesce((select sum(case when s.day = pm.joined_on then greatest(s.steps - pm.base, 0) else s.steps end) from public.step_days s where s.user_id = pm.user_id and s.day >= pm.joined_on and s.day <= pk.ends_on), 0)::bigint from public.pack_members pm join public.packs pk on pk.id = pm.pack_id where pm.pack_id = p_pack and pm.user_id = p_user $fn$;
revoke execute on function public.pack_score(uuid, uuid) from public, anon, authenticated;

create or replace function public.person_challenges(p_user uuid, p_skip uuid default null) returns integer language sql stable security definer set search_path = public as $fn$ select ((select count(*) from public.duels d where d.kind = 'person' and d.id is distinct from p_skip and ((d.status = 'active' and (d.a_ref = p_user::text or d.b_ref = p_user::text)) or (d.status = 'pending' and d.a_ref = p_user::text)) and (d.ends_on is null or d.ends_on >= current_date)) + (select count(*) from public.pack_members pm join public.packs pk on pk.id = pm.pack_id where pm.user_id = p_user and pk.ends_on >= current_date))::int $fn$;

create or replace function public.create_pack(p_name text, p_days integer) returns table(id uuid, join_code text) language plpgsql security definer set search_path = public as $fn$ declare me uuid := auth.uid(); n int := greatest(1, least(coalesce(p_days, 7), 30)); code text; pid uuid; base int; begin if me is null then raise exception 'Sign in first'; end if; if char_length(trim(coalesce(p_name, ''))) < 2 then raise exception 'Give your pack war a name of at least 2 characters'; end if; if public.person_challenges(me) >= 3 then raise exception 'You already have 3 challenges. Finish one to start another.'; end if; loop code := upper(substr(md5(random()::text || clock_timestamp()::text), 1, 6)); exit when not exists (select 1 from public.packs x where x.join_code = code); end loop; insert into public.packs (name, created_by, days, starts_on, ends_on, join_code) values (left(trim(p_name), 40), me, n, current_date, current_date + n - 1, code) returning packs.id into pid; select coalesce(s.steps, 0) into base from public.step_days s where s.user_id = me and s.day = current_date; insert into public.pack_members (pack_id, user_id, joined_on, base) values (pid, me, current_date, coalesce(base, 0)); return query select pid, code; end $fn$;
create or replace function public.join_pack(p_code text) returns table(id uuid, name text) language plpgsql security definer set search_path = public as $fn$ declare me uuid := auth.uid(); pk public.packs; base int; begin if me is null then raise exception 'Sign in first'; end if; select * into pk from public.packs where join_code = upper(trim(coalesce(p_code, ''))); if pk.id is null then raise exception 'We could not find that pack war'; end if; if pk.ends_on < current_date then raise exception 'That pack war has finished'; end if; if exists (select 1 from public.pack_members where pack_id = pk.id and user_id = me) then return query select pk.id, pk.name; return; end if; if (select count(*) from public.pack_members where pack_id = pk.id) >= 30 then raise exception 'That pack war is full'; end if; if public.person_challenges(me) >= 3 then raise exception 'You already have 3 challenges. Finish one to join another.'; end if; select coalesce(s.steps, 0) into base from public.step_days s where s.user_id = me and s.day = current_date; insert into public.pack_members (pack_id, user_id, joined_on, base) values (pk.id, me, current_date, coalesce(base, 0)); return query select pk.id, pk.name; end $fn$;
create or replace function public.my_packs() returns table(id uuid, name text, join_code text, starts_on date, ends_on date, days_left integer, finished boolean, members integer, my_steps bigint, my_rank integer, is_owner boolean) language sql stable security definer set search_path = public as $fn$ with mine as (select pk.* from public.packs pk join public.pack_members pm on pm.pack_id = pk.id where pm.user_id = auth.uid() and pk.ends_on >= current_date - 2), sc as (select m.id as pid, pm.user_id, public.pack_score(m.id, pm.user_id) as s from mine m join public.pack_members pm on pm.pack_id = m.id) select m.id, m.name, m.join_code, m.starts_on, m.ends_on, greatest(0, m.ends_on - current_date + 1)::int, m.ends_on < current_date, (select count(*) from sc where sc.pid = m.id)::int, coalesce((select s from sc where sc.pid = m.id and sc.user_id = auth.uid()), 0), (1 + (select count(*) from sc where sc.pid = m.id and sc.s > coalesce((select s from sc c2 where c2.pid = m.id and c2.user_id = auth.uid()), 0)))::int, m.created_by = auth.uid() from mine m order by m.ends_on, m.created_at $fn$;
create or replace function public.pack_board(p_id uuid) returns table(display_name text, steps bigint, bowls integer, is_me boolean, is_owner boolean) language sql stable security definer set search_path = public as $fn$ select p.display_name, public.pack_score(p_id, pm.user_id), public.milestone_count(public.pack_score(p_id, pm.user_id)), pm.user_id = auth.uid(), pm.user_id = pk.created_by from public.pack_members pm join public.packs pk on pk.id = pm.pack_id join public.profiles p on p.user_id = pm.user_id where pm.pack_id = p_id and exists (select 1 from public.pack_members me where me.pack_id = p_id and me.user_id = auth.uid()) order by 2 desc, 1 $fn$;
create or replace function public.leave_pack(p_id uuid) returns void language plpgsql security definer set search_path = public as $fn$ begin delete from public.pack_members where pack_id = p_id and user_id = auth.uid(); end $fn$;
revoke execute on function public.create_pack(text, integer), public.join_pack(text), public.my_packs(), public.pack_board(uuid), public.leave_pack(uuid) from public, anon;
grant execute on function public.create_pack(text, integer), public.join_pack(text), public.my_packs(), public.pack_board(uuid), public.leave_pack(uuid) to authenticated;

-- Pack leaderboard: running pack wars ranked by steps per walker.
create or replace function public.pack_leaderboard() returns table(id uuid, name text, members integer, total_steps bigint, steps_per_member bigint, days_left integer, is_mine boolean) language sql stable security definer set search_path = public as $fn$ with sc as (select pk.id as pid, pm.user_id, public.pack_score(pk.id, pm.user_id) as s from public.packs pk join public.pack_members pm on pm.pack_id = pk.id where pk.ends_on >= current_date) select pk.id, pk.name, count(*)::int, sum(sc.s)::bigint, (sum(sc.s) / count(*))::bigint, greatest(0, pk.ends_on - current_date + 1)::int, bool_or(sc.user_id = auth.uid()) from sc join public.packs pk on pk.id = sc.pid group by pk.id order by 5 desc, pk.name limit 50 $fn$;
revoke execute on function public.pack_leaderboard() from public, anon; grant execute on function public.pack_leaderboard() to authenticated;

-- Any member can rename the pack war.
create or replace function public.rename_pack(p_id uuid, p_name text) returns void language plpgsql security definer set search_path = public as $fn$ begin if char_length(trim(coalesce(p_name, ''))) < 2 then raise exception 'Give your pack war a name of at least 2 characters'; end if; update public.packs k set name = left(trim(p_name), 40) where k.id = p_id and exists (select 1 from public.pack_members pm where pm.pack_id = k.id and pm.user_id = auth.uid()); if not found then raise exception 'You are not in that pack war'; end if; end $fn$;
revoke execute on function public.rename_pack(uuid, text) from public, anon; grant execute on function public.rename_pack(uuid, text) to authenticated;
